async(tab=postTab,cdp=postCdp)=>{let r=await cdp.send('Runtime.evaluate',{expression:`new Promise(resolve=>{const began=performance.now();const check=()=>{const root=document.querySelector('#pf-app,[data-timing-source-detail]');if(root?.dataset.timingReady){requestAnimationFrame(()=>requestAnimationFrame(()=>resolve({url:location.href,entry:document.querySelector('script[type="module"]')?.getAttribute('src'),ready:root.dataset.timingReady,navigationMs:Number(root.dataset.timingNavigationMs),measurements:JSON.parse(root.dataset.timingMeasurements||'[]'),width:innerWidth,height:innerHeight,overflow:document.documentElement.scrollWidth>innerWidth,brokenImages:[...document.images].filter(i=>i.getBoundingClientRect().width>0&&(!i.complete||!i.naturalWidth)).map(i=>i.src),mainRows:[...document.querySelectorAll('.chart>.chart-row .stage strong')].map(x=>x.innerText),postRows:[...document.querySelectorAll('#branch-post .flow-work-timelines .stage strong')].map(x=>x.innerText),text:root.innerText})));return}if(performance.now()-began>4000){resolve({error:'ready timeout'});return}requestAnimationFrame(check)};check()})`,awaitPromise:true,returnByValue:true});return r.result.value}

async(selector,key,n)=>{await postTab.playwright.locator(selector).click();let r=await postReady(),m=r.measurements.at(-1);postActions.push({key,iteration:n,elapsedMs:m?.elapsedMs,action:m?.action,url:r.url,entry:r.entry,overflow:r.overflow,brokenImages:r.brokenImages});await savePost();if(r.error||r.entry!=='/assets/index-CowAGUVp.js'||!m||r.overflow||r.brokenImages.length)throw Error(JSON.stringify({key,error:r.error,entry:r.entry,m}));return r}

async(from,to)=>{for(const scene of postManifest.scenes.slice(from,to)){for(let n=0;n<5;n++){if(await postTab.url()===postManifest.base+scene.path)await postTab.reload();else await postTab.goto(postManifest.base+scene.path);let r=await postReady();postPages.push({scene:scene.key,mode:'cold',iteration:n,entry:r.entry,elapsedMs:r.navigationMs,url:r.url,overflow:r.overflow,brokenImages:r.brokenImages,mainRows:r.mainRows});await postTab.reload();r=await postReady();postPages.push({scene:scene.key,mode:'refresh',iteration:n,entry:r.entry,elapsedMs:r.navigationMs,url:r.url,overflow:r.overflow,brokenImages:r.brokenImages});await postTab.playwright.getByRole('combobox',{name:'演示场景',exact:true}).selectOption(scene.key==='normal'?'fullContract':'normal');await postReady();await postTab.playwright.getByRole('combobox',{name:'演示场景',exact:true}).selectOption(scene.key);r=await postReady();postPages.push({scene:scene.key,mode:'spa',iteration:n,entry:r.entry,elapsedMs:r.measurements.at(-1)?.elapsedMs,url:r.url,overflow:r.overflow,brokenImages:r.brokenImages});await savePost();}for(let n=0;n<5;n++){let r=await postAct('.stage [data-expand="post"]','post-open:'+scene.key,n);if(r.postRows.length!==4)throw Error('missing nested rows');await postAct('#branch-post .branch-head [data-expand="post"]','post-close:'+scene.key,n);}}return {pages:postPages.length,actions:postActions.length,max:Math.max(...postPages.map(r=>r.elapsedMs),...postActions.map(r=>r.elapsedMs))}}